INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Cold-Chain Integrity Advisory Platform | Operations Tower</title>\n  <!-- Tailwind CSS -->\n  <script src="https://cdn.tailwindcss.com"></script>\n  <!-- Leaflet CSS & JS -->\n  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />\n  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>\n  <!-- Chart.js -->\n  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: \'#eff6ff\',\n              100: \'#dbeafe\',\n              500: \'#3b82f6\',\n              600: \'#2563eb\',\n              700: \'#1d4ed8\',\n              900: \'#1e3a8a\',\n            }\n          }\n        }\n      }\n    }\n  </script>\n  <style>\n    #map { height: 380px; width: 100%; border-radius: 0.75rem; }\n    .pulse-dot {\n      width: 12px;\n      height: 12px;\n      background: #22c55e;\n      border-radius: 50%;\n      box-shadow: 0 0 0 rgba(34, 197, 94, 0.4);\n      animation: pulse 1.8s infinite;\n    }\n    @keyframes pulse {\n      0% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7); }\n      70% { box-shadow: 0 0 0 10px rgba(34, 197, 94, 0); }\n      100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }\n    }\n  </style>\n</head>\n<body class="bg-slate-50 text-slate-800 font-sans antialiased min-h-screen flex flex-col">\n\n  <!-- Top Navbar -->\n  <header class="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">\n      <div class="flex items-center space-x-3">\n        <div class="w-10 h-10 rounded-lg bg-blue-600 flex items-center justify-center text-white font-bold text-lg shadow-md shadow-blue-500/20">\n          ❄️\n        </div>\n        <div>\n          <div class="font-extrabold text-slate-900 tracking-tight text-lg flex items-center gap-2">\n            ColdChain <span class="text-blue-600">Integrity Advisor</span>\n            <span class="text-xs bg-emerald-100 text-emerald-800 font-semibold px-2 py-0.5 rounded-full">India Operations</span>\n          </div>\n          <p class="text-xs text-slate-500">National Vaccine & Biopharma Cold-Chain Operations Tower (CDSCO / WHO GDP)</p>\n        </div>\n      </div>\n      <div class="flex items-center space-x-3">\n        <button onclick="openAdvisoryModal()" class="inline-flex items-center gap-1.5 px-3.5 py-2 text-xs font-semibold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition">\n          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7"></path></svg>\n          Plan Route & Risk Advisor\n        </button>\n        <button onclick="downloadActivePdf()" class="inline-flex items-center gap-1.5 px-3.5 py-2 text-xs font-semibold text-slate-700 bg-white border border-slate-300 hover:bg-slate-50 rounded-lg shadow-sm transition">\n          <svg class="w-4 h-4 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>\n          Audit Certificate (PDF)\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Main Container -->\n  <main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 flex-1 w-full space-y-6">\n\n    <!-- Excursion Alert Banner (Hidden by default, shown when excursion occurs) -->\n    <div id="alertBanner" class="hidden bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg shadow-sm">\n      <div class="flex items-center justify-between">\n        <div class="flex items-center space-x-3">\n          <span class="text-2xl">⚠️</span>\n          <div>\n            <h4 class="text-sm font-bold text-red-800" id="alertTitle">CRITICAL TEMPERATURE EXCURSION DETECTED</h4>\n            <p class="text-xs text-red-700" id="alertDesc">Cargo temperature has exceeded the upper threshold. Re-routing advisory activated.</p>\n          </div>\n        </div>\n        <button onclick="resolveExcursion()" class="px-3 py-1.5 text-xs font-semibold text-red-800 bg-red-100 hover:bg-red-200 border border-red-300 rounded-md transition">\n          Restore Active Cooling\n        </button>\n      </div>\n    </div>\n\n    <!-- Top Stats Row -->\n    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">\n      <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">\n        <div>\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Active Shipments</p>\n          <p class="text-2xl font-extrabold text-slate-900 mt-1" id="statActive">3</p>\n          <span class="inline-flex items-center text-xs font-medium text-emerald-600 mt-1">● 100% GPS Streaming</span>\n        </div>\n        <div class="w-12 h-12 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center text-xl">🚚</div>\n      </div>\n      <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">\n        <div>\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Cold Integrity Index</p>\n          <p class="text-2xl font-extrabold text-emerald-600 mt-1" id="statIntegrity">98.8%</p>\n          <span class="text-xs text-slate-500">WHO GDP Compliant</span>\n        </div>\n        <div class="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-lg flex items-center justify-center text-xl">🛡️</div>\n      </div>\n      <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">\n        <div>\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Selected Payload Temp</p>\n          <p class="text-2xl font-extrabold text-slate-900 mt-1" id="statTemp">4.2°C</p>\n          <span class="text-xs text-slate-500" id="statBounds">Spec: 2.0°C to 8.0°C</span>\n        </div>\n        <div class="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-lg flex items-center justify-center text-xl">🌡️</div>\n      </div>\n      <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">\n        <div>\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Mean Kinetic Temp (MKT)</p>\n          <p class="text-2xl font-extrabold text-slate-900 mt-1" id="statMkt">4.38°C</p>\n          <span class="text-xs text-slate-500">USP &lt;1151&gt; Arrhenius</span>\n        </div>\n        <div class="w-12 h-12 bg-purple-50 text-purple-600 rounded-lg flex items-center justify-center text-xl">📊</div>\n      </div>\n    </div>\n\n    <!-- Map & Live Telemetry Chart Row -->\n    <div class="grid grid-cols-1 lg:grid-cols-12 gap-6">\n      <!-- Interactive Transit Map (7 cols) -->\n      <div class="lg:col-span-7 bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">\n        <div class="flex items-center justify-between mb-3">\n          <div class="flex items-center space-x-2">\n            <span class="pulse-dot"></span>\n            <h3 class="text-sm font-bold text-slate-900">Live Cold-Chain Corridor Map</h3>\n          </div>\n          <span class="text-xs text-slate-500" id="mapSub">Displaying Active Telemetry Trails</span>\n        </div>\n        <div id="map"></div>\n      </div>\n\n      <!-- Real-Time Telemetry Curve (5 cols) -->\n      <div class="lg:col-span-5 bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between">\n        <div>\n          <div class="flex items-center justify-between mb-2">\n            <h3 class="text-sm font-bold text-slate-900">Live Temperature Trajectory</h3>\n            <span class="text-xs bg-slate-100 text-slate-600 px-2 py-0.5 rounded font-mono" id="chartDevice">SN-8921</span>\n          </div>\n          <p class="text-xs text-slate-500 mb-3">Telemetry samples ingested every 60s against regulatory bands.</p>\n          <div class="h-64">\n            <canvas id="telemetryChart"></canvas>\n          </div>\n        </div>\n        <!-- Demo Stress Button -->\n        <div class="mt-4 pt-3 border-t border-slate-100 flex items-center justify-between">\n          <span class="text-xs text-slate-500">Demo Controls:</span>\n          <button id="stressBtn" onclick="triggerExcursion()" class="px-3 py-1.5 text-xs font-semibold text-rose-700 bg-rose-50 hover:bg-rose-100 border border-rose-200 rounded-lg transition">\n            ⚡ Simulate Refrigerator Breakdown\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Active Shipments Table -->\n    <div class="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">\n      <div class="px-5 py-4 border-b border-slate-100 flex items-center justify-between">\n        <div>\n          <h3 class="text-sm font-bold text-slate-900">Active Monitored Shipments</h3>\n          <p class="text-xs text-slate-500">Click a shipment to switch telemetry focus and inspect route parameters.</p>\n        </div>\n        <span class="text-xs text-blue-600 font-semibold bg-blue-50 px-2.5 py-1 rounded-full">Auto-Refreshing (5s)</span>\n      </div>\n      <div class="overflow-x-auto">\n        <table class="w-full text-left border-collapse text-xs">\n          <thead>\n            <tr class="bg-slate-50 text-slate-600 font-semibold border-b border-slate-200">\n              <th class="py-3 px-4">Shipment ID</th>\n              <th class="py-3 px-4">Payload Category</th>\n              <th class="py-3 px-4">Route</th>\n              <th class="py-3 px-4">Cargo Temp</th>\n              <th class="py-3 px-4">Target Spec</th>\n              <th class="py-3 px-4">Ambient Weather</th>\n              <th class="py-3 px-4">Risk Index</th>\n              <th class="py-3 px-4">Status</th>\n              <th class="py-3 px-4 text-right">Actions</th>\n            </tr>\n          </thead>\n          <tbody id="shipmentsTableBody" class="divide-y divide-slate-100 text-slate-700">\n            <!-- Dynamically populated -->\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n  </main>\n\n  <!-- Route Advisory Modal -->\n  <div id="advisoryModal" class="hidden fixed inset-0 bg-slate-900/70 backdrop-blur-sm flex items-center justify-center p-4" style="z-index: 99999;">\n    <div class="bg-white rounded-2xl max-w-xl w-full shadow-2xl border border-slate-100 overflow-hidden transform transition-all relative">\n      <div class="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">\n        <div>\n          <h3 class="text-base font-bold flex items-center gap-2">\n            <span>🗺️</span> Pre-Transit Route Climate & Risk Advisory\n          </h3>\n          <p class="text-xs text-slate-300">Model weather corridor exposure before truck departure</p>\n        </div>\n        <button onclick="closeAdvisoryModal()" class="text-slate-400 hover:text-white text-xl font-bold p-1">✕</button>\n      </div>\n      <div class="p-6 space-y-4 max-h-[85vh] overflow-y-auto">\n        <!-- Quick Indian Corridors Presets -->\n        <div>\n          <label class="block text-xs font-semibold text-slate-500 mb-1.5 uppercase tracking-wider">Quick Select Indian Pharma Corridors:</label>\n          <div class="flex flex-wrap gap-1.5">\n            <button type="button" onclick="setPreset(\'Pune SII Bio-Hub, Maharashtra\', \'New Delhi AIIMS Central Medical Depot\', \'Refrigerated (2°C to 8°C)\', 24)" class="px-2.5 py-1 text-[11px] bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-700 font-medium rounded border border-slate-200 transition">\n              📍 Pune ➔ Delhi (NH 48)\n            </button>\n            <button type="button" onclick="setPreset(\'Hyderabad Genome Valley, Telangana\', \'Bengaluru Biocon Cluster, Karnataka\', \'Refrigerated (2°C to 8°C)\', 18)" class="px-2.5 py-1 text-[11px] bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-700 font-medium rounded border border-slate-200 transition">\n              📍 Hyderabad ➔ Bengaluru (NH 44)\n            </button>\n            <button type="button" onclick="setPreset(\'Ahmedabad Biotech Hub, Gujarat\', \'Mumbai Central Cold Storage, Maharashtra\', \'Frozen (-25°C to -15°C)\', 14)" class="px-2.5 py-1 text-[11px] bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-700 font-medium rounded border border-slate-200 transition">\n              📍 Ahmedabad ➔ Mumbai\n            </button>\n            <button type="button" onclick="setPreset(\'New Delhi AIIMS Central Medical Depot\', \'Kolkata Eastern Regional Depo, West Bengal\', \'Refrigerated (2°C to 8°C)\', 28)" class="px-2.5 py-1 text-[11px] bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-700 font-medium rounded border border-slate-200 transition">\n              📍 Delhi ➔ Kolkata (NH 19)\n            </button>\n            <button type="button" onclick="setPreset(\'Mumbai Central Cold Storage, Maharashtra\', \'Chennai TNMSC Central Depot, Tamil Nadu\', \'Refrigerated (2°C to 8°C)\', 26)" class="px-2.5 py-1 text-[11px] bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-700 font-medium rounded border border-slate-200 transition">\n              📍 Mumbai ➔ Chennai (NH 48)\n            </button>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-4">\n          <div>\n            <label class="block text-xs font-semibold text-slate-600 mb-1">Origin Pharma Hub</label>\n            <input type="text" id="advOrigin" value="Pune SII Bio-Hub, Maharashtra" class="w-full px-3 py-2 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-600 mb-1">Destination Depo / Hospital</label>\n            <input type="text" id="advDest" value="New Delhi AIIMS Central Medical Depot" class="w-full px-3 py-2 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n          </div>\n        </div>\n        <div>\n          <label class="block text-xs font-semibold text-slate-600 mb-1">Payload Category</label>\n          <select id="advCategory" class="w-full px-3 py-2 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n            <option value="Refrigerated (2°C to 8°C)">Refrigerated (2°C to 8°C) — Vaccines & Biologics</option>\n            <option value="Ultra-Cold (-80°C to -60°C)">Ultra-Cold (-80°C to -60°C) — mRNA & Cell Therapy</option>\n            <option value="Frozen (-25°C to -15°C)">Frozen (-25°C to -15°C) — Plasma & Diagnostics</option>\n            <option value="Controlled Room Temp (15°C to 25°C)">Controlled Room Temp (15°C to 25°C) — Standard Pharma</option>\n          </select>\n        </div>\n        <div>\n          <label class="block text-xs font-semibold text-slate-600 mb-1">Insulation Capacity Rating (Passive Hours)</label>\n          <input type="number" id="advInsulation" value="24" class="w-full px-3 py-2 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n        </div>\n\n        <button id="calcBtn" onclick="calculateAdvisory()" class="w-full py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg text-xs shadow-md transition flex items-center justify-center gap-2">\n          <span>Run Route Climate Simulation</span>\n        </button>\n\n        <!-- Advisory Result Container -->\n        <div id="advResult" class="hidden mt-4 p-4 rounded-xl border space-y-3 bg-slate-50 border-slate-200">\n          <div class="flex items-center justify-between border-b pb-2">\n            <div>\n              <span class="text-xs uppercase tracking-wider font-bold text-slate-500">Route Risk Score</span>\n              <div class="text-2xl font-extrabold" id="resScore">78 / 100</div>\n            </div>\n            <span class="px-3 py-1 rounded-full text-xs font-bold" id="resBadge">Critical Risk</span>\n          </div>\n          <p class="text-xs text-slate-700 leading-relaxed font-medium" id="resRec"></p>\n          <div class="text-xs text-slate-600 grid grid-cols-2 gap-2 border-t pt-2">\n            <div><strong>Corridor Max Ambient:</strong> <span id="resAmbient"></span></div>\n            <div><strong>Suggested Window:</strong> <span id="resWindow"></span></div>\n          </div>\n          <div class="text-xs text-slate-600 border-t pt-2">\n            <strong>Recommended Cold Storage Checkpoints:</strong>\n            <ul id="resCheckpoints" class="list-disc pl-4 text-[11px] text-slate-600 mt-1 space-y-0.5"></ul>\n          </div>\n          <div class="pt-2">\n            <button onclick="dispatchNewShipment()" class="w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg text-xs shadow-md transition flex items-center justify-center gap-2">\n              <span>🚀 Dispatch Shipment & Track Live on Map</span>\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n          <p class="text-xs text-slate-700 leading-relaxed" id="resRec"></p>\n          <div class="text-xs text-slate-600 border-t pt-2 space-y-1">\n            <p><strong>Suggested Departure:</strong> <span id="resWindow"></span></p>\n            <p><strong>Corridor Ambient Peak:</strong> <span id="resAmbient"></span></p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    let activeShipmentId = "SHP-SII-101";\n    let map, markers = {}, polylineLayer, originMarker, destMarker;\n    let telemetryChart;\n\n    function setPreset(orig, dest, cat, hours) {\n      document.getElementById(\'advOrigin\').value = orig;\n      document.getElementById(\'advDest\').value = dest;\n      document.getElementById(\'advCategory\').value = cat;\n      document.getElementById(\'advInsulation\').value = hours;\n    }\n\n    // Initialize Leaflet Map centered on India\n    function initMap() {\n      map = L.map(\'map\').setView([21.5, 78.9], 5);\n      L.tileLayer(\'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png\', {\n        attribution: \'&copy; OpenStreetMap contributors\'\n      }).addTo(map);\n    }\n\n    // Initialize Chart.js\n    function initChart() {\n      const ctx = document.getElementById(\'telemetryChart\').getContext(\'2d\');\n      telemetryChart = new Chart(ctx, {\n        type: \'line\',\n        data: {\n          labels: [],\n          datasets: [\n            {\n              label: \'Cargo Temp (°C)\',\n              borderColor: \'#2563eb\',\n              backgroundColor: \'rgba(37, 99, 235, 0.08)\',\n              data: [],\n              borderWidth: 2.2,\n              tension: 0.3,\n              fill: true\n            },\n            {\n              label: \'Ambient Weather (°C)\',\n              borderColor: \'#94a3b8\',\n              borderDash: [5, 5],\n              data: [],\n              borderWidth: 1.5,\n              tension: 0.2,\n              fill: false\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { position: \'top\', labels: { boxWidth: 12, font: { size: 10 } } }\n          },\n          scales: {\n            x: { ticks: { font: { size: 9 } } },\n            y: { ticks: { font: { size: 9 } } }\n          }\n        }\n      });\n    }\n\n    // Fetch and render data\n    async function loadData() {\n      try {\n        const res = await fetch(\'/api/shipments\');\n        const shipments = await res.json();\n        renderTable(shipments);\n\n        const current = shipments.find(s => s.id === activeShipmentId) || shipments[0];\n        if (current) {\n          updateActiveShipmentUI(current);\n        }\n      } catch (e) {\n        console.error("Failed to load telemetry:", e);\n      }\n    }\n\n    function renderTable(shipments) {\n      const tbody = document.getElementById(\'shipmentsTableBody\');\n      tbody.innerHTML = \'\';\n\n      shipments.forEach(s => {\n        const isSelected = s.id === activeShipmentId;\n        const statusClass = s.status === \'AT_RISK\' ? \'bg-red-100 text-red-800\' : \'bg-emerald-100 text-emerald-800\';\n        const riskClass = s.risk_score > 60 ? \'text-red-600\' : (s.risk_score > 35 ? \'text-amber-600\' : \'text-emerald-600\');\n\n        const tr = document.createElement(\'tr\');\n        tr.className = `cursor-pointer transition hover:bg-slate-50 ${isSelected ? \'bg-blue-50/70 font-semibold\' : \'\'}`;\n        tr.onclick = () => selectShipment(s.id);\n\n        tr.innerHTML = `\n          <td class="py-3 px-4 font-mono font-bold text-blue-700">${s.id}</td>\n          <td class="py-3 px-4"><div class="font-medium text-slate-900">${s.payload_name}</div><span class="text-[10px] text-slate-500">${s.category}</span></td>\n          <td class="py-3 px-4">${s.origin.split(\',\')[0]} → ${s.destination.split(\',\')[0]}</td>\n          <td class="py-3 px-4 text-sm font-bold ${s.current_temp > s.max_temp || s.current_temp < s.min_temp ? \'text-red-600\' : \'text-slate-900\'}">${s.current_temp}°C</td>\n          <td class="py-3 px-4 font-mono">${s.min_temp}°C to ${s.max_temp}°C</td>\n          <td class="py-3 px-4 text-slate-500">${s.current_ambient}°C</td>\n          <td class="py-3 px-4 font-bold ${riskClass}">${s.risk_score} / 100</td>\n          <td class="py-3 px-4"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${statusClass}">${s.status}</span></td>\n          <td class="py-3 px-4 text-right">\n            <a href="/api/shipments/${s.id}/audit-pdf" target="_blank" class="px-2.5 py-1 text-[11px] font-semibold text-blue-600 bg-white border border-blue-200 rounded hover:bg-blue-50">PDF Cert</a>\n          </td>\n        `;\n        tbody.appendChild(tr);\n\n        // Update map marker\n        if (!markers[s.id]) {\n          const marker = L.marker([s.current_lat, s.current_lng]).addTo(map);\n          marker.bindPopup(`<b>${s.payload_name}</b><br/>Temp: ${s.current_temp}°C<br/>Status: ${s.status}`);\n          markers[s.id] = marker;\n        } else {\n          markers[s.id].setLatLng([s.current_lat, s.current_lng]);\n          markers[s.id].setPopupContent(`<b>${s.payload_name}</b><br/>Temp: ${s.current_temp}°C<br/>Status: ${s.status}`);\n        }\n      });\n    }\n\n    function selectShipment(id) {\n      activeShipmentId = id;\n      loadData();\n    }\n\n    function updateActiveShipmentUI(s) {\n      document.getElementById(\'statTemp\').innerText = `${s.current_temp}°C`;\n      document.getElementById(\'statBounds\').innerText = `Spec: ${s.min_temp}°C to ${s.max_temp}°C`;\n      document.getElementById(\'statMkt\').innerText = `${s.mkt_temp}°C`;\n      document.getElementById(\'chartDevice\').innerText = s.tracking_number;\n      document.getElementById(\'mapSub\').innerText = `${s.payload_name} (${s.origin.split(\',\')[0]} to ${s.destination.split(\',\')[0]})`;\n\n      // Excursion banner check\n      const banner = document.getElementById(\'alertBanner\');\n      if (s.status === \'AT_RISK\' || s.current_temp > s.max_temp) {\n        banner.classList.remove(\'hidden\');\n        document.getElementById(\'alertTitle\').innerText = `CRITICAL EXCURSION: ${s.id} (${s.payload_name})`;\n        document.getElementById(\'alertDesc\').innerText = `Temperature breached upper specification (${s.current_temp}°C vs threshold ${s.max_temp}°C). Re-icing advisory sent to driver.`;\n      } else {\n        banner.classList.add(\'hidden\');\n      }\n\n      // Update Chart\n      const history = s.history || [];\n      telemetryChart.data.labels = history.map(h => h.timestamp);\n      telemetryChart.data.datasets[0].data = history.map(h => h.temperature);\n      telemetryChart.data.datasets[1].data = history.map(h => h.ambient_temp);\n      telemetryChart.update();\n\n      // Draw route on map\n      if (polylineLayer) {\n        map.removeLayer(polylineLayer);\n      }\n      if (originMarker) {\n        map.removeLayer(originMarker);\n      }\n      if (destMarker) {\n        map.removeLayer(destMarker);\n      }\n\n      if (s.route_waypoints && s.route_waypoints.length > 0) {\n        const color = s.status === \'AT_RISK\' ? \'#ef4444\' : \'#2563eb\';\n        polylineLayer = L.polyline(s.route_waypoints, { color: color, weight: 4.5, opacity: 0.85 }).addTo(map);\n        \n        // Add start and end hub pins\n        const startPt = s.route_waypoints[0];\n        const endPt = s.route_waypoints[s.route_waypoints.length - 1];\n        \n        originMarker = L.circleMarker(startPt, {\n          radius: 7,\n          color: \'#16a34a\',\n          fillColor: \'#22c55e\',\n          fillOpacity: 0.9,\n          weight: 2\n        }).addTo(map);\n        originMarker.bindPopup(`<b>Dispatch Hub:</b> ${s.origin}`);\n\n        destMarker = L.circleMarker(endPt, {\n          radius: 7,\n          color: \'#b91c1c\',\n          fillColor: \'#ef4444\',\n          fillOpacity: 0.9,\n          weight: 2\n        }).addTo(map);\n        destMarker.bindPopup(`<b>Receiving Depo:</b> ${s.destination}`);\n\n        // Zoom map to fit the full highway route\n        map.fitBounds(polylineLayer.getBounds(), { padding: [45, 45], maxZoom: 7 });\n      }\n    }\n\n    async function triggerExcursion() {\n      await fetch(`/api/shipments/${activeShipmentId}/trigger-excursion`, { method: \'POST\' });\n      loadData();\n    }\n\n    async function resolveExcursion() {\n      await fetch(`/api/shipments/${activeShipmentId}/resolve-excursion`, { method: \'POST\' });\n      loadData();\n    }\n\n    function downloadActivePdf() {\n      window.open(`/api/shipments/${activeShipmentId}/audit-pdf`, \'_blank\');\n    }\n\n    // Modal functions\n    function openAdvisoryModal() {\n      document.getElementById(\'advisoryModal\').classList.remove(\'hidden\');\n    }\n    function closeAdvisoryModal() {\n      document.getElementById(\'advisoryModal\').classList.add(\'hidden\');\n    }\n\n    async function calculateAdvisory() {\n      const btn = document.getElementById(\'calcBtn\');\n      const originalText = btn.innerHTML;\n      btn.innerHTML = `<span>⏳ Simulating Corridor Weather...</span>`;\n      btn.disabled = true;\n\n      try {\n        const payload = {\n          origin: document.getElementById(\'advOrigin\').value,\n          destination: document.getElementById(\'advDest\').value,\n          payload_category: document.getElementById(\'advCategory\').value,\n          insulation_hours: parseInt(document.getElementById(\'advInsulation\').value) || 24\n        };\n\n        const res = await fetch(\'/api/advisory/plan\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n\n        const resultBox = document.getElementById(\'advResult\');\n        resultBox.classList.remove(\'hidden\');\n        document.getElementById(\'resScore\').innerText = `${data.risk_score} / 100`;\n        document.getElementById(\'resRec\').innerText = data.recommendation;\n        document.getElementById(\'resWindow\').innerText = data.suggested_departure_window;\n        document.getElementById(\'resAmbient\').innerText = `${data.corridor_max_ambient}°C`;\n\n        // Checkpoints\n        const cpList = document.getElementById(\'resCheckpoints\');\n        cpList.innerHTML = \'\';\n        (data.cold_storage_checkpoints || []).forEach(cp => {\n          const li = document.createElement(\'li\');\n          li.innerText = cp;\n          cpList.appendChild(li);\n        });\n\n        const badge = document.getElementById(\'resBadge\');\n        badge.innerText = data.risk_level;\n        if (data.risk_score >= 70) {\n          badge.className = "px-3 py-1 rounded-full text-xs font-bold bg-red-100 text-red-800";\n        } else if (data.risk_score >= 40) {\n          badge.className = "px-3 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-800";\n        } else {\n          badge.className = "px-3 py-1 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800";\n        }\n\n        // Dynamically draw the simulated highway route on the map\n        if (data.route_geometry && data.route_geometry.length > 0) {\n          if (polylineLayer) map.removeLayer(polylineLayer);\n          if (originMarker) map.removeLayer(originMarker);\n          if (destMarker) map.removeLayer(destMarker);\n\n          const rColor = data.risk_score >= 70 ? \'#ef4444\' : (data.risk_score >= 40 ? \'#f59e0b\' : \'#10b981\');\n          polylineLayer = L.polyline(data.route_geometry, { color: rColor, weight: 5, opacity: 0.9, dashArray: \'6, 6\' }).addTo(map);\n\n          originMarker = L.circleMarker(data.route_geometry[0], {\n            radius: 8, color: \'#16a34a\', fillColor: \'#22c55e\', fillOpacity: 1, weight: 2\n          }).addTo(map);\n          originMarker.bindPopup(`<b>Simulated Origin:</b> ${payload.origin}`);\n\n          destMarker = L.circleMarker(data.route_geometry[data.route_geometry.length - 1], {\n            radius: 8, color: \'#b91c1c\', fillColor: \'#ef4444\', fillOpacity: 1, weight: 2\n          }).addTo(map);\n          destMarker.bindPopup(`<b>Simulated Destination:</b> ${payload.destination}`);\n\n          map.fitBounds(polylineLayer.getBounds(), { padding: [50, 50], maxZoom: 7 });\n        }\n      } catch (err) {\n        alert("Failed to compute advisory. Please check server status.");\n        console.error(err);\n      } finally {\n        btn.innerHTML = originalText;\n        btn.disabled = false;\n      }\n    }\n\n    async function dispatchNewShipment() {\n      try {\n        const payload = {\n          origin: document.getElementById(\'advOrigin\').value,\n          destination: document.getElementById(\'advDest\').value,\n          payload_category: document.getElementById(\'advCategory\').value,\n          insulation_hours: parseInt(document.getElementById(\'advInsulation\').value) || 24\n        };\n\n        const res = await fetch(\'/api/shipments/dispatch\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify(payload)\n        });\n        const newShipment = await res.json();\n\n        // Switch to the newly dispatched shipment\n        activeShipmentId = newShipment.id;\n        closeAdvisoryModal();\n        await loadData();\n        alert(`Shipment ${newShipment.id} successfully dispatched! Now tracking live on the corridor map.`);\n      } catch (err) {\n        alert("Failed to dispatch shipment.");\n        console.error(err);\n      }\n    }\n\n    // Close on Escape or click outside\n    document.addEventListener(\'keydown\', (e) => {\n      if (e.key === \'Escape\') closeAdvisoryModal();\n    });\n    document.getElementById(\'advisoryModal\').addEventListener(\'click\', (e) => {\n      if (e.target.id === \'advisoryModal\') closeAdvisoryModal();\n    });\n\n    window.onload = () => {\n      initMap();\n      initChart();\n      loadData();\n      // Polling every 5 seconds\n      setInterval(loadData, 5000);\n    };\n  </script>\n</body>\n</html>\n'
